import util from 'node:util';
import { preprocess } from 'svelte/compiler';
import ts from 'typescript';
import { staticStateMetaKey } from '../../config';
import * as hmr from '../hmr';
import { readFile, writeFile } from '../utils/fileUtils';
import { toMagicString } from '../utils/magicStringUtils';
import { isModule } from '../utils/componentUtils';
const createAst = (code, id) => {
    return ts.createSourceFile(id, code, ts.ScriptTarget.Latest, true);
};
const allowedExtensions = ['.svelte.ts', '.svelte.js', '.svelte'];
const isAllowedExtension = (id) => {
    return allowedExtensions.some((ext) => id.endsWith(ext));
};
const isSvelteComponent = (id) => {
    return id.endsWith('.svelte');
};
const hasStaticState = (code) => {
    return code.includes('extends StaticState');
};
const regex = /extends StaticState[^\{]*{/gm;
const appendMeta = (code, meta) => {
    // add meta info to the code: id
    return code.replace(regex, `$& ${staticStateMetaKey} = ${JSON.stringify(meta)}`);
};
const isExtendsStaticState = (node) => {
    if (node.kind !== ts.SyntaxKind.ClassDeclaration)
        return false;
    const n = node;
    return !!n.heritageClauses?.some((clause) => {
        return clause.getFullText().includes('StaticState');
    });
};
const isClassWithName = (node, name) => {
    if (!node.name)
        return false;
    if (node.name.kind !== ts.SyntaxKind.Identifier)
        return false;
    if (node.name.getText() !== name)
        return false;
    return true;
};
const extractMembers = (node) => {
    const members = [];
    node.members.forEach((member) => {
        if (member.kind !== ts.SyntaxKind.PropertyDeclaration)
            return;
        const modifiers = [];
        ts.getJSDocTags(member).forEach((tag) => {
            modifiers.push({
                name: tag.tagName.getText(),
                value: tag.comment?.toString() ?? ''
            });
        });
        if (!member.name || member.name.kind !== ts.SyntaxKind.Identifier)
            return;
        const m = member;
        if (!m.initializer || m.initializer.kind !== ts.SyntaxKind.CallExpression)
            return;
        const mi = m.initializer;
        const args = mi.arguments;
        if (args.length !== 1)
            return;
        const arg = args[0];
        members.push({
            name: member.name.getText(),
            argument: {
                start: arg.pos,
                end: arg.end
            },
            modifiers
        });
    });
    return members;
};
const transformScript = (code, id, module) => {
    const members = [];
    // Recursive function to traverse the AST
    function traverse(node, depth = 0) {
        if (isExtendsStaticState(node)) {
            members.push(...extractMembers(node));
        }
        ts.forEachChild(node, (childNode) => traverse(childNode, depth + 1));
    }
    // Start traversing the AST from the source file
    traverse(createAst(code, id));
    const meta = {
        id,
        members,
        module
    };
    return appendMeta(code, meta);
};
export const transformStaticState = async (code, id) => {
    if (!isAllowedExtension(id))
        return code;
    if (!hasStaticState(code))
        return code;
    if (isSvelteComponent(id)) {
        const processed = await preprocess(code, {
            script: ({ content, attributes }) => {
                const module = isModule(attributes);
                return {
                    code: transformScript(content, id, module)
                };
            }
        }, {
            filename: id
        });
        return processed.code;
    }
    else {
        return transformScript(code, id, false);
    }
};
const mutateScript = (code, id, className, propertyName, value) => {
    let needsRewrite = false;
    const ms = toMagicString(code);
    // Recursive function to traverse the AST
    function traverse(node, depth = 0) {
        if (isExtendsStaticState(node) && isClassWithName(node, className)) {
            const members = extractMembers(node);
            const member = members.find((m) => m.name === propertyName);
            if (!member)
                return;
            ms.overwrite(member.argument.start, member.argument.end, util.inspect(value, {
                maxArrayLength: Infinity,
                maxStringLength: Infinity,
                breakLength: Infinity,
                depth: Infinity
            }));
            needsRewrite = true;
        }
        ts.forEachChild(node, (childNode) => traverse(childNode, depth + 1));
    }
    // Start traversing the AST from the source file
    traverse(createAst(code, id));
    return {
        code: ms.toString(),
        needsRewrite
    };
};
export const mutateStaticState = async (id, module, className, propertyName, value) => {
    if (!isAllowedExtension(id))
        return;
    const content = readFile(id);
    if (!hasStaticState(content))
        return;
    if (isSvelteComponent(id)) {
        let needsRewrite = false;
        const processed = await preprocess(content, {
            script: ({ content, attributes }) => {
                // If the module attribute is different from the module flag, the
                // class we're looking for is in a different script block, skip the
                // mutation
                if (isModule(attributes) !== module)
                    return;
                if (!hasStaticState(content))
                    return;
                const mutatedScript = mutateScript(content, id, className, propertyName, value);
                needsRewrite = mutatedScript.needsRewrite;
                return {
                    code: mutatedScript.code
                };
            }
        }, {
            filename: id
        });
        if (needsRewrite) {
            writeFile(id, processed.code);
            hmr.disableModuleHmr(id);
        }
    }
    else {
        const { code, needsRewrite } = mutateScript(content, id, className, propertyName, value);
        if (needsRewrite) {
            writeFile(id, code);
            hmr.disableModuleHmr(id);
        }
    }
};
